  type: "available"
  at: Date
}

interface UserStatusUnavailable {
  type: "unavailable"
  at: Date
}

interface UserStatusUnknown {
  type: "unknown"
  at?: Date
}

type UserStatus = UserStatusAvailable | UserStatusUnavailable | UserStatusUnknown
const UserStatus = new EntitySchema<UserStatus>({
  name: "UserStatus",
  embeddable: true,
  properties: {
    type: { name: "type", type: "enum", items: ["available", "unavailable", "unknown"] },
    at: { name: "at", type: "datetime", nullable: true },
  },
})

interface User {
  id: string
  firstName: string
  lastName: string
  status: UserStatus
}
const User = new EntitySchema<User>({
  name: "User",
  tableName: "users",
  properties: {
    id: { name: "id", type: "uuid", primary: true },
    firstName: { name: "first_name", type: "text" },
    lastName: { name: "last_name", type: "text" },
    status: { name: "status", kind: "embedded", object: true, entity: () => UserStatus }
  }
})

const orm = await MikroORM.init({
  entities: [UserStatus, User],
  dbName: "postgres",
  user: "postgres",
  password: "",
  host: "localhost",
  port: 5432,
  debug: true,
})

const em = orm.em.fork()

const users = em.findAll(User, {
  where: {
    status: {
      type: { $in: ["available", "unavailable"] }
    }
  }
})

console.log(users)
```

Mikro-orm generates the query correctly but provides a type error on the `$in` clause because it's a union. The filter criteria type safety may need to use something like (https://github.com/sindresorhus/type-fest/blob/main/source/all-union-fields.d.ts)[AllUnionFields] from type-fest.

